// All game audio, synthesised with the Web Audio API: no sound files.
//
// - Sound effects are short synth "recipes" (oscillators + filtered noise).
// - Music is a slow ambient space loop generated by a small sequencer, with a
//   calmer mood for menus/shop and a pulse layer added during battles.
// - Browsers only allow audio after the player touches the page, so nothing
//   plays until `unlock()` runs from the first tap/click/key press.
// - Settings (music, effects, mute) are saved per device.

export type Sfx =
  | 'laser' | 'torpedo' | 'hit' | 'block' | 'explode' | 'boom' | 'heal' | 'jam' | 'zap' | 'spawn'
  | 'revive' | 'buff' | 'debuff' | 'cloak' | 'ram' | 'engage' | 'overload'
  | 'click' | 'select' | 'buy' | 'merge' | 'levelup' | 'sell' | 'reroll' | 'freeze' | 'unfreeze'
  | 'power' | 'arm' | 'error' | 'relic' | 'victory' | 'defeat' | 'draw' | 'rankup' | 'launch';

export type Mood = 'menu' | 'shop' | 'battle';

export interface AudioSettings {
  music: number; // 0..1
  sfx: number; // 0..1
  muted: boolean;
}

const KEY = 'starbrawl.audio';
const DEFAULTS: AudioSettings = { music: 0.6, sfx: 0.8, muted: false };

/** Smallest gap between two plays of the same effect, so fast battles don't turn to noise. */
const MIN_GAP: Partial<Record<Sfx, number>> = {
  laser: 45, torpedo: 70, hit: 40, block: 60, explode: 70, boom: 90, heal: 80, jam: 80, zap: 60,
  spawn: 80, buff: 70, debuff: 70, cloak: 90, click: 30, select: 30, reroll: 60,
};
const MAX_VOICES = 18;
/** Only these frequent battle sounds count toward the voice cap; explosions, results and UI always play. */
const CAPPED = new Set<Sfx>(['laser', 'torpedo', 'hit', 'block', 'heal', 'jam', 'zap', 'spawn', 'buff', 'debuff', 'cloak']);
/** Roughly how long each capped sound rings, in seconds. */
const LENGTH: Partial<Record<Sfx, number>> = {
  laser: 0.1, torpedo: 0.3, hit: 0.08, block: 0.17, heal: 0.22, jam: 0.15, zap: 0.13, spawn: 0.13, buff: 0.13, debuff: 0.13, cloak: 0.32,
};

const midi = (n: number) => 440 * Math.pow(2, (n - 69) / 12);

class AudioEngine {
  private ctx: AudioContext | null = null;
  private master!: GainNode;
  private sfxBus!: GainNode;
  private musicBus!: GainNode;
  private echo!: DelayNode;
  private noise!: AudioBuffer;
  private last = new Map<Sfx, number>();
  private voiceEnds: number[] = [];
  private mood: Mood = 'menu';
  private timer: number | null = null;
  private nextBeat = 0;
  private beat = 0;
  settings: AudioSettings;

  constructor() {
    this.settings = { ...DEFAULTS };
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) {
        const s = JSON.parse(raw) as Partial<AudioSettings>;
        const num = (v: unknown, d: number) => (typeof v === 'number' && Number.isFinite(v) ? Math.max(0, Math.min(1, v)) : d);
        this.settings = { music: num(s.music, DEFAULTS.music), sfx: num(s.sfx, DEFAULTS.sfx), muted: s.muted === true };
      }
    } catch {
      /* storage blocked: use defaults */
    }
  }

  /** Muted, or both volumes at zero: the game makes no sound at all. */
  private get silent() {
    return this.settings.muted || (this.settings.music <= 0 && this.settings.sfx <= 0);
  }

  /** Call from a user gesture. Safe to call many times. */
  unlock() {
    // iPhones treat web audio as "ambient" by default: it mixes with other apps' audio, and
    // the silent switch mutes it. "playback" makes the game audible like a video, but it also
    // pauses the player's own music or audiobook, so only ask for it when our music is on.
    const nav = navigator as unknown as { audioSession?: { type: string } };
    if (nav.audioSession) {
      const type = !this.settings.muted && this.settings.music > 0 ? 'playback' : 'ambient';
      try { if (nav.audioSession.type !== type) nav.audioSession.type = type; } catch { /* not supported */ }
    }
    // Silent: keep the audio engine stopped, so it never holds the device's audio.
    if (this.silent) {
      if (this.ctx?.state === 'running') void this.ctx.suspend();
      return;
    }
    if (!this.ctx) {
      const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!Ctor) return;
      this.ctx = new Ctor();
      this.build();
    }
    // 'suspended' normally, or 'interrupted' on iOS after a call or Siri.
    if (this.ctx.state !== 'running') this.ctx.resume().catch(() => { /* retried on the next tap */ });
    // Older iOS only truly unlocks once something plays inside the gesture.
    const blip = this.ctx.createBufferSource();
    blip.buffer = this.ctx.createBuffer(1, 1, this.ctx.sampleRate);
    blip.connect(this.ctx.destination);
    blip.start();
    this.startMusic();
  }

  get ready() {
    return !!this.ctx && this.ctx.state === 'running';
  }

  private build() {
    const ctx = this.ctx!;
    // A gentle compressor keeps stacked explosions from clipping.
    const comp = ctx.createDynamicsCompressor();
    // Hard-ish knee: it only steps in near the top, so normal sounds keep their punch.
    comp.threshold.value = -8;
    comp.knee.value = 4;
    comp.ratio.value = 6;
    comp.attack.value = 0.003;
    comp.release.value = 0.2;
    this.master = ctx.createGain();
    this.master.connect(comp).connect(ctx.destination);
    this.sfxBus = ctx.createGain();
    this.sfxBus.connect(this.master);
    this.musicBus = ctx.createGain();
    this.musicBus.connect(this.master);
    // Echo used by the music's twinkles.
    this.echo = ctx.createDelay(1);
    this.echo.delayTime.value = 0.42;
    const fb = ctx.createGain();
    fb.gain.value = 0.38;
    const tone = ctx.createBiquadFilter();
    tone.type = 'lowpass';
    tone.frequency.value = 2200;
    this.echo.connect(tone).connect(fb).connect(this.echo);
    tone.connect(this.musicBus);
    // One second of white noise, reused by every noisy effect.
    this.noise = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
    const data = this.noise.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    this.apply();
    // Pause everything while the tab is hidden; timers get throttled there anyway.
    document.addEventListener('visibilitychange', () => {
      if (!this.ctx) return;
      if (document.hidden) void this.ctx.suspend();
      else if (!this.silent) this.ctx.resume().catch(() => { /* resumes on the next tap */ });
    });
  }

  // ---------- settings ----------

  private apply() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const m = this.settings.muted ? 0 : 1;
    this.sfxBus.gain.setTargetAtTime(this.settings.sfx * 1.0 * m, t, 0.02);
    this.musicBus.gain.setTargetAtTime(this.settings.music * 1.0 * m, t, 0.1);
  }

  update(patch: Partial<AudioSettings>) {
    this.settings = { ...this.settings, ...patch };
    this.settings.music = Math.max(0, Math.min(1, this.settings.music));
    this.settings.sfx = Math.max(0, Math.min(1, this.settings.sfx));
    try { localStorage.setItem(KEY, JSON.stringify(this.settings)); } catch { /* ignore */ }
    this.apply();
    this.unlock(); // settings change from a tap: start, stop or switch the audio session to match
  }

  // ---------- building blocks ----------

  /** Reserve a voice; false when too many sounds are already playing. */
  private voice(end: number) {
    const now = this.ctx!.currentTime;
    this.voiceEnds = this.voiceEnds.filter((e) => e > now);
    if (this.voiceEnds.length >= MAX_VOICES) return false;
    this.voiceEnds.push(end);
    return true;
  }

  /** One oscillator note with a pitch sweep and a quick attack/decay envelope. */
  private tone(o: {
    type: OscillatorType; f0: number; f1?: number; at?: number; dur: number; vol: number;
    bus?: AudioNode; attack?: number; curve?: 'exp' | 'lin';
  }) {
    const ctx = this.ctx!;
    const t = ctx.currentTime + (o.at ?? 0);
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = o.type;
    osc.frequency.setValueAtTime(o.f0, t);
    if (o.f1 !== undefined) {
      if (o.curve === 'lin') osc.frequency.linearRampToValueAtTime(o.f1, t + o.dur);
      else osc.frequency.exponentialRampToValueAtTime(Math.max(20, o.f1), t + o.dur);
    }
    const a = o.attack ?? 0.004;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(o.vol, t + a);
    g.gain.exponentialRampToValueAtTime(0.0001, t + o.dur);
    osc.connect(g).connect(o.bus ?? this.sfxBus);
    osc.start(t);
    osc.stop(t + o.dur + 0.05);
  }

  /** A burst of filtered noise, with an optional filter sweep. */
  private hiss(o: {
    type: BiquadFilterType; f0: number; f1?: number; q?: number; at?: number; dur: number; vol: number; bus?: AudioNode;
  }) {
    const ctx = this.ctx!;
    const t = ctx.currentTime + (o.at ?? 0);
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = o.type;
    f.Q.value = o.q ?? 1;
    f.frequency.setValueAtTime(o.f0, t);
    if (o.f1 !== undefined) f.frequency.exponentialRampToValueAtTime(Math.max(20, o.f1), t + o.dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(o.vol, t + 0.004);
    g.gain.exponentialRampToValueAtTime(0.0001, t + o.dur);
    src.connect(f).connect(g).connect(o.bus ?? this.sfxBus);
    src.start(t, Math.random() * 0.5);
    src.stop(t + o.dur + 0.05);
  }

  private notes(type: OscillatorType, seq: number[], step: number, dur: number, vol: number) {
    seq.forEach((n, i) => this.tone({ type, f0: midi(n), at: i * step, dur, vol }));
  }

  // ---------- sound effects ----------

  /**
   * Play an effect. `pitch` shifts it (1 = normal); enemy shots use a lower pitch
   * so the two sides sound different.
   */
  play(name: Sfx, pitch = 1) {
    if (!this.ready || this.settings.muted || this.settings.sfx <= 0) return;
    const now = performance.now();
    const gap = MIN_GAP[name] ?? 0;
    if (gap && now - (this.last.get(name) ?? -1e9) < gap) return;
    this.last.set(name, now);
    if (CAPPED.has(name) && !this.voice(this.ctx!.currentTime + (LENGTH[name] ?? 0.3))) return;
    const p = pitch * (0.96 + Math.random() * 0.08); // small natural variation
    this.recipe(name, p);
  }

  private recipe(name: Sfx, p: number) {
    switch (name) {
      // Battle
      case 'laser':
        this.tone({ type: 'square', f0: 1400 * p, f1: 260 * p, dur: 0.09, vol: 0.12 });
        break;
      case 'torpedo':
        this.hiss({ type: 'bandpass', f0: 300, f1: 1400, q: 3, dur: 0.28, vol: 0.22 });
        this.tone({ type: 'triangle', f0: 140 * p, f1: 70 * p, dur: 0.25, vol: 0.12 });
        break;
      case 'hit':
        this.hiss({ type: 'highpass', f0: 1200, dur: 0.06, vol: 0.11 });
        this.tone({ type: 'square', f0: 220 * p, f1: 70 * p, dur: 0.07, vol: 0.05 });
        break;
      case 'block':
        this.tone({ type: 'triangle', f0: 1500 * p, dur: 0.16, vol: 0.12 });
        this.tone({ type: 'sine', f0: 2250 * p, dur: 0.1, vol: 0.06 });
        break;
      case 'explode':
        this.hiss({ type: 'lowpass', f0: 1600, f1: 120, dur: 0.45, vol: 0.27 });
        this.tone({ type: 'sine', f0: 110 * p, f1: 32, dur: 0.4, vol: 0.23 });
        break;
      case 'boom': // big ships
        this.hiss({ type: 'lowpass', f0: 1200, f1: 60, dur: 0.8, vol: 0.33 });
        this.tone({ type: 'sine', f0: 80 * p, f1: 24, dur: 0.7, vol: 0.3 });
        this.tone({ type: 'square', f0: 60 * p, f1: 30, dur: 0.3, vol: 0.06 });
        break;
      case 'heal':
        this.notes('sine', [76, 79, 84], 0.05, 0.12, 0.07);
        break;
      case 'jam':
        for (let i = 0; i < 4; i++) this.tone({ type: 'square', f0: (i % 2 ? 260 : 340) * p, at: i * 0.035, dur: 0.035, vol: 0.05 });
        break;
      case 'zap':
        this.tone({ type: 'sawtooth', f0: 2200 * p, f1: 300 * p, dur: 0.12, vol: 0.07 });
        this.hiss({ type: 'highpass', f0: 3000, dur: 0.08, vol: 0.08 });
        break;
      case 'spawn':
        this.tone({ type: 'sine', f0: 420 * p, f1: 950 * p, dur: 0.12, vol: 0.07 });
        break;
      case 'revive':
        this.notes('triangle', [60, 64, 67, 72, 76], 0.05, 0.18, 0.09);
        break;
      case 'buff':
        this.notes('square', [76, 83], 0.05, 0.08, 0.05);
        break;
      case 'debuff':
        this.notes('square', [71, 64], 0.05, 0.08, 0.05);
        break;
      case 'cloak':
        this.tone({ type: 'sine', f0: 1100 * p, f1: 300 * p, dur: 0.3, vol: 0.06, attack: 0.05 });
        break;
      case 'ram':
        this.hiss({ type: 'lowpass', f0: 900, f1: 200, dur: 0.25, vol: 0.25 });
        this.tone({ type: 'square', f0: 300 * p, f1: 60 * p, dur: 0.22, vol: 0.08 });
        break;
      case 'engage':
        this.notes('square', [62, 69, 62, 69], 0.1, 0.09, 0.06);
        break;
      case 'overload':
        this.tone({ type: 'sawtooth', f0: 80, f1: 400, dur: 0.6, vol: 0.1, curve: 'lin' });
        this.tone({ type: 'square', f0: 82, f1: 410, dur: 0.6, vol: 0.05, curve: 'lin' });
        break;
      // Shop and menus
      case 'click':
        this.tone({ type: 'square', f0: 1100 * p, dur: 0.03, vol: 0.05 });
        break;
      case 'select':
        this.tone({ type: 'triangle', f0: 760 * p, dur: 0.05, vol: 0.07 });
        break;
      case 'buy':
        this.notes('square', [83, 88], 0.06, 0.1, 0.06);
        break;
      case 'merge':
        this.notes('triangle', [67, 71, 74, 79], 0.04, 0.14, 0.09);
        break;
      case 'levelup':
        this.notes('square', [72, 76, 79, 84], 0.07, 0.12, 0.06);
        this.tone({ type: 'triangle', f0: midi(84), at: 0.28, dur: 0.35, vol: 0.08 });
        break;
      case 'sell':
        this.notes('square', [88, 83, 76], 0.05, 0.08, 0.05);
        break;
      case 'reroll':
        for (let i = 0; i < 4; i++) this.hiss({ type: 'bandpass', f0: 1800 + i * 500, q: 6, at: i * 0.045, dur: 0.04, vol: 0.14 });
        break;
      case 'freeze':
        this.tone({ type: 'sine', f0: 2100, f1: 1500, dur: 0.3, vol: 0.06 });
        this.tone({ type: 'sine', f0: 2800, f1: 2000, at: 0.03, dur: 0.25, vol: 0.04 });
        break;
      case 'unfreeze':
        this.tone({ type: 'sine', f0: 1500, f1: 2100, dur: 0.18, vol: 0.05 });
        break;
      case 'arm':
        this.tone({ type: 'triangle', f0: 500, f1: 800, dur: 0.1, vol: 0.07 });
        break;
      case 'power':
        this.tone({ type: 'sawtooth', f0: 200, f1: 900, dur: 0.25, vol: 0.06 });
        this.notes('sine', [84, 88, 91, 96], 0.05, 0.15, 0.06);
        break;
      case 'error':
        this.tone({ type: 'square', f0: 160, dur: 0.08, vol: 0.06 });
        this.tone({ type: 'square', f0: 140, at: 0.1, dur: 0.1, vol: 0.06 });
        break;
      case 'relic':
        this.notes('triangle', [69, 72, 76, 81, 84], 0.06, 0.3, 0.08);
        break;
      case 'launch':
        this.tone({ type: 'sawtooth', f0: 120, f1: 600, dur: 0.45, vol: 0.06 });
        this.hiss({ type: 'bandpass', f0: 400, f1: 2400, q: 1.5, dur: 0.5, vol: 0.12 });
        break;
      // Results
      case 'victory':
        this.notes('square', [72, 76, 79], 0.11, 0.12, 0.1);
        this.tone({ type: 'square', f0: midi(84), at: 0.33, dur: 0.6, vol: 0.1 });
        this.tone({ type: 'triangle', f0: midi(72), at: 0.33, dur: 0.6, vol: 0.12 });
        break;
      case 'defeat':
        this.notes('triangle', [67, 63, 60], 0.2, 0.3, 0.14);
        this.tone({ type: 'sawtooth', f0: midi(48), at: 0.4, dur: 0.7, vol: 0.07 });
        break;
      case 'draw':
        this.notes('triangle', [67, 67], 0.18, 0.2, 0.08);
        break;
      case 'rankup':
        this.notes('square', [67, 72, 76, 79, 84, 88], 0.08, 0.14, 0.06);
        this.tone({ type: 'triangle', f0: midi(91), at: 0.48, dur: 0.6, vol: 0.08 });
        break;
    }
  }

  // ---------- music ----------

  /** Which music mood to play. Scenes call this from create(). */
  setMood(m: Mood) {
    this.mood = m;
  }

  private startMusic() {
    if (this.timer !== null || !this.ctx) return;
    this.nextBeat = this.ctx.currentTime + 0.2;
    this.beat = 0;
    // Schedule a little ahead on a timer, so notes land exactly on the beat.
    this.timer = window.setInterval(() => this.schedule(), 120);
  }

  private schedule() {
    const ctx = this.ctx;
    if (!ctx || ctx.state !== 'running') return;
    // Behind schedule (a pause or a slow frame): skip ahead instead of firing old beats all at once.
    if (this.nextBeat < ctx.currentTime) this.nextBeat = ctx.currentTime + 0.05;
    while (this.nextBeat < ctx.currentTime + 0.4) {
      if (!this.settings.muted && this.settings.music > 0) this.musicBeat(this.beat, this.nextBeat);
      this.nextBeat += BEAT;
      this.beat++;
    }
  }

  private musicBeat(b: number, t: number) {
    const bar = Math.floor(b / 4);
    const inBar = b % 4;
    const chord = PROGRESSION[bar % PROGRESSION.length];
    const battle = this.mood === 'battle';

    // Pad: a new chord every bar, slow swell, dark filter.
    if (inBar === 0) for (const n of chord.pad) this.pad(midi(n), t, BEAT * 4.6, battle ? 0.05 : 0.06);
    // Bass: root on beats 1 and 3 (just beat 1 on the menu).
    if (inBar === 0 || (inBar === 2 && this.mood !== 'menu')) this.bass(midi(chord.root), t, BEAT * 1.8, 0.12);
    // Twinkles: sparse notes from the scale, into the echo.
    for (const off of [0, 0.5]) {
      const chance = battle ? 0.42 : this.mood === 'shop' ? 0.3 : 0.22;
      if (Math.random() < chance) {
        const n = SCALE[Math.floor(Math.random() * SCALE.length)];
        this.twinkle(midi(n), t + off * BEAT, 0.035);
      }
    }
    // Battle pulse: soft low thump on every beat, a tick on the off-beats.
    if (battle) {
      this.thump(t, 0.16);
      this.tick(t + BEAT / 2, 0.03);
    }
  }

  private pad(f: number, t: number, dur: number, vol: number) {
    const ctx = this.ctx!;
    const g = ctx.createGain();
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.setValueAtTime(500, t);
    lp.frequency.linearRampToValueAtTime(1100, t + dur * 0.5);
    lp.frequency.linearRampToValueAtTime(500, t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vol, t + 1.2);
    g.gain.setValueAtTime(vol, t + dur - 1.4);
    g.gain.linearRampToValueAtTime(0.0001, t + dur);
    lp.connect(g).connect(this.musicBus);
    for (const det of [-7, 7]) {
      const o = ctx.createOscillator();
      o.type = 'sawtooth';
      o.frequency.value = f;
      o.detune.value = det;
      o.connect(lp);
      o.start(t);
      o.stop(t + dur + 0.1);
    }
  }

  private bass(f: number, t: number, dur: number, vol: number) {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = 'sine';
    o.frequency.value = f;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.05);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.musicBus);
    o.start(t);
    o.stop(t + dur + 0.05);
  }

  private twinkle(f: number, t: number, vol: number) {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = 'triangle';
    o.frequency.value = f;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.6);
    o.connect(g);
    g.connect(this.musicBus);
    g.connect(this.echo);
    o.start(t);
    o.stop(t + 0.65);
  }

  private thump(t: number, vol: number) {
    const ctx = this.ctx!;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(120, t);
    o.frequency.exponentialRampToValueAtTime(42, t + 0.18);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
    o.connect(g).connect(this.musicBus);
    o.start(t);
    o.stop(t + 0.25);
  }

  private tick(t: number, vol: number) {
    const ctx = this.ctx!;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const f = ctx.createBiquadFilter();
    f.type = 'highpass';
    f.frequency.value = 7000;
    const g = ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.04);
    src.connect(f).connect(g).connect(this.musicBus);
    src.start(t, Math.random() * 0.5);
    src.stop(t + 0.05);
  }
}

// Music theory for the loop: A minor, slow (about 66 BPM), four chords.
const BEAT = 60 / 66;
const PROGRESSION = [
  { root: 33, pad: [57, 60, 64, 67] }, // Am7
  { root: 29, pad: [57, 60, 64, 65] }, // Fmaj7
  { root: 36, pad: [55, 59, 60, 64] }, // Cmaj7
  { root: 28, pad: [55, 59, 62, 64] }, // Em7
];
const SCALE = [69, 72, 74, 76, 79, 81, 84, 86, 88]; // A minor pentatonic, upper octaves

export const audio = new AudioEngine();

/** Wire the first user gesture to unlock audio (browsers block it until then). */
export function installAudioUnlock() {
  (window as unknown as { __audio: AudioEngine }).__audio = audio; // for console debugging
  const go = () => audio.unlock();
  for (const ev of ['pointerdown', 'touchend', 'keydown']) window.addEventListener(ev, go, { capture: true, passive: true });
}
